(function(){'use strict';var DB_NAME='mowology-receipts';var DB_VERSION=1;var STORE_NAME='pending-receipts';var db=null;var _isSyncing=!1;function openDB(){return new Promise(function(resolve,reject){if(db){resolve(db);return}
if(!window.indexedDB){reject(new Error('IndexedDB not supported'));return}
var request=indexedDB.open(DB_NAME,DB_VERSION);request.onupgradeneeded=function(e){var database=e.target.result;if(!database.objectStoreNames.contains(STORE_NAME)){database.createObjectStore(STORE_NAME,{keyPath:'id',autoIncrement:!0})}};request.onsuccess=function(e){db=e.target.result;resolve(db)};request.onerror=function(){reject(new Error('Failed to open IndexedDB'))}})}
function queue(file,lat,lng,csrf){return openDB().then(function(database){return new Promise(function(resolve,reject){var tx=database.transaction(STORE_NAME,'readwrite');var store=tx.objectStore(STORE_NAME);var record={blob:file,lat:lat||null,lng:lng||null,csrf:csrf||'',timestamp:Date.now()};var req=store.add(record);req.onsuccess=function(){resolve(req.result)};req.onerror=function(){reject(new Error('Failed to queue receipt'))};tx.oncomplete=function(){registerSync();updatePendingBadge()}})})}
function getPendingCount(){return openDB().then(function(database){return new Promise(function(resolve){var tx=database.transaction(STORE_NAME,'readonly');var store=tx.objectStore(STORE_NAME);var countReq=store.count();countReq.onsuccess=function(){resolve(countReq.result)};countReq.onerror=function(){resolve(0)}})}).catch(function(){return 0})}
function registerSync(){if('serviceWorker' in navigator&&'SyncManager' in window){navigator.serviceWorker.ready.then(function(reg){return reg.sync.register('receipt-upload')}).catch(function(){})}}
function syncNow(){if(_isSyncing)return Promise.resolve({uploaded:0,failed:0});_isSyncing=!0;return openDB().then(function(database){return new Promise(function(resolve){var tx=database.transaction(STORE_NAME,'readonly');var store=tx.objectStore(STORE_NAME);var getAll=store.getAll();getAll.onsuccess=function(){var receipts=getAll.result||[];if(!receipts.length){_isSyncing=!1;resolve({uploaded:0,failed:0});return}
var uploaded=0;var failed=0;var chain=Promise.resolve();receipts.forEach(function(receipt){chain=chain.then(function(){return uploadOne(receipt).then(function(ok){if(ok){uploaded++;return deleteRecord(receipt.id)}else{failed++}})})});chain.then(function(){_isSyncing=!1;if(uploaded>0){updatePendingBadge()}else{getPendingCount().then(function(count){var badge=document.getElementById('mw-offline-pending-count');if(badge)badge.textContent=count})}
resolve({uploaded:uploaded,failed:failed})})};getAll.onerror=function(){_isSyncing=!1;resolve({uploaded:0,failed:0})}})}).catch(function(){_isSyncing=!1;return{uploaded:0,failed:0}})}
function uploadOne(receipt){var csrf=(typeof window.CSRF==='string'&&window.CSRF)?window.CSRF:(receipt.csrf||'');var formData=new FormData();formData.append('receipt_photo',receipt.blob,'receipt.jpg');formData.append('csrf_token',csrf);if(receipt.lat)formData.append('lat',receipt.lat);if(receipt.lng)formData.append('lng',receipt.lng);return fetch('/crm/api/receipt-intake.php',{method:'POST',body:formData}).then(function(r){return r.ok}).catch(function(){return!1})}
function deleteRecord(id){return openDB().then(function(database){return new Promise(function(resolve){var tx=database.transaction(STORE_NAME,'readwrite');tx.objectStore(STORE_NAME).delete(id);tx.oncomplete=function(){resolve()};tx.onerror=function(){resolve()}})})}
function updatePendingBadge(){getPendingCount().then(function(count){var banner=document.getElementById('mw-offline-banner');var badge=document.getElementById('mw-offline-pending-count');if(count>0){if(badge)badge.textContent=count;if(banner&&!isOnline()){banner.style.display='flex'}else if(banner&&isOnline()&&count>0){banner.style.display='flex';banner.classList.add('mw-offline-syncing');var bannerText=banner.querySelector('.mw-offline-text');if(bannerText)bannerText.textContent='Syncing '+count+' receipt(s)...';syncNow().then(function(result){if(result.uploaded>0){if(bannerText)bannerText.textContent=result.uploaded+' receipt(s) synced!';banner.classList.remove('mw-offline-syncing');banner.classList.add('mw-offline-success');setTimeout(function(){banner.style.display='none';banner.classList.remove('mw-offline-success')},3000);if(typeof loadExpenses==='function')loadExpenses();}})}}else{if(banner&&isOnline()){banner.style.display='none'}}})}
function isOnline(){if(window.MwNative&&typeof window.MwNative.network==='object'){return window.MwNative.network.isOnline!==!1}
return navigator.onLine!==!1}
function init(){openDB().catch(function(){});window.addEventListener('online',function(){var banner=document.getElementById('mw-offline-banner');if(banner){banner.classList.remove('mw-offline-offline');banner.classList.add('mw-offline-syncing')}
updatePendingBadge()});window.addEventListener('offline',function(){var banner=document.getElementById('mw-offline-banner');if(banner){banner.style.display='flex';banner.classList.add('mw-offline-offline');banner.classList.remove('mw-offline-syncing','mw-offline-success');var bannerText=banner.querySelector('.mw-offline-text');if(bannerText){getPendingCount().then(function(count){bannerText.textContent=count>0?'Offline — '+count+' receipt(s) pending':'Offline — receipts will queue automatically'})}}});if(window.MwNative&&window.MwNative.network){window.MwNative.network.onStatusChange(function(connected){var banner=document.getElementById('mw-offline-banner');if(connected){if(banner){banner.classList.remove('mw-offline-offline');banner.classList.add('mw-offline-syncing')}
updatePendingBadge()}else{if(banner){banner.style.display='flex';banner.classList.add('mw-offline-offline');banner.classList.remove('mw-offline-syncing','mw-offline-success');var bannerText=banner.querySelector('.mw-offline-text');if(bannerText){getPendingCount().then(function(count){bannerText.textContent=count>0?'Offline — '+count+' receipt(s) pending':'Offline — receipts will queue automatically'})}}}})}
document.addEventListener('visibilitychange',function(){if(document.visibilityState==='visible'&&isOnline()){getPendingCount().then(function(count){if(count>0){updatePendingBadge()}})}});window.addEventListener('focus',function(){if(isOnline()){getPendingCount().then(function(count){if(count>0){updatePendingBadge()}})}});if('serviceWorker' in navigator){navigator.serviceWorker.addEventListener('message',function(e){if(e.data&&e.data.type==='receipts-synced'){updatePendingBadge();if(typeof loadExpenses==='function')loadExpenses();}})}
updatePendingBadge()}
window.OfflineReceipts={init:init,queue:queue,remove:deleteRecord,getPendingCount:getPendingCount,syncNow:syncNow,updatePendingBadge:updatePendingBadge}})()